CREATE TABLE public.quiz_attempts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), quiz_id UUID NOT NULL REFERENCES public.quizzes(id) ON DELETE CASCADE, player_name TEXT NOT NULL, player_phone TEXT, score INTEGER NOT NULL DEFAULT 0, total_questions INTEGER NOT NULL DEFAULT 0, percentage NUMERIC(5,2) NOT NULL DEFAULT 0, time_taken_seconds INTEGER NOT NULL DEFAULT 0, passed BOOLEAN NOT NULL DEFAULT false, created_at TIMESTAMPTZ NOT NULL DEFAULT now()); ALTER TABLE public.quiz_attempts ENABLE ROW LEVEL SECURITY; CREATE POLICY "Public read attempts" ON public.quiz_attempts FOR SELECT USING (true); CREATE POLICY "Anyone can submit attempt" ON public.quiz_attempts FOR INSERT WITH CHECK (true); CREATE POLICY "Admin manage attempts" ON public.quiz_attempts FOR ALL USING (has_role(auth.uid(), 'admin'::app_role)); CREATE INDEX idx_quiz_attempts_quiz_score ON public.quiz_attempts(quiz_id, score DESC, time_taken_seconds ASC); CREATE OR REPLACE FUNCTION public.increment_quiz_attempt(qid uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN UPDATE public.quizzes SET attempt_count = attempt_count + 1 WHERE id = qid; END; $$;